var DATA = {"mode": "dims", "w": 17, "d": 13, "fits": "ATX builds with full-size GPUs"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="dims"){
  show("Footprint",DATA.w+" x "+DATA.d+" in");
  show("Area",(DATA.w*DATA.d)+" sq in");
  show("Typical for",DATA.fits);
}else if(m==="load"){
  show("Component weight",DATA.comp+" kg");
  show("Bench rated",DATA.rated+" kg");
  show("Margin",(Math.round((DATA.rated-DATA.comp)*10)/10)+" kg");
  show("Safe",DATA.comp<DATA.rated?"YES":"NO - over limit");
}else if(m==="standoffs"){
  show("Form factors",DATA.forms.join(", "));
  show("Mounting","brass standoffs in pre-drilled pattern");
}else if(m==="layout"){
  console.log("Bench zones:");
  DATA.zones.forEach(function(z,i){console.log("  "+(i+1)+". "+z);});
}else if(m==="compat"){
  show("Check",DATA.item+" on "+DATA.tray);
  show("Fits",DATA.ok?"YES":"NO - needs a larger tray");
}else if(m==="airflow"){
  show("Design","open air - no panels, no trapped heat");
  show("GPU clearance",DATA.clear+" mm to nearest rail");
}else if(m==="assembly"){
  show("Board to POST",DATA.min+" minutes typical");
  show("Why fast","no panels, no cable origami");
}else if(m==="checklist"){
  console.log("Pre-power checklist:");
  DATA.items.forEach(function(x,i){console.log("  "+(i+1)+". "+x);});
}else if(m==="gpu"){
  show("Max GPU length",DATA.len+" mm");
  show("Support","adjustable bracket included");
}else if(m==="psu"){
  show("PSU mount",DATA.mount);
  show("Supports","ATX and SFX (with adapter)");
}else if(m==="stack"){
  show("Stackable",DATA.n+" high on locating pins");
}else if(m==="compare"){
  show("Open bench","fast swaps, best airflow, more dust");
  show("Closed case","filtered, quieter, slower to service");
}else if(m==="workflow"){
  console.log("Review-bench workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
}
console.log("DEMO_OK");

